pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address recipient) public {
        vm.assume(recipient != address(c) && recipient != address(0));

        uint256 balanceBefore = address(c).balance;

        (bool ok, ) = address(c).call(abi.encodeWithSignature("getFirstWithdrawalBonus(address)", recipient));

        if (ok) {
            uint256 balanceAfter = address(c).balance;
            assertTrue(balanceAfter == balanceBefore - 100, "Balance should decrease by exactly 100 after successful call");
        } else {
            // If it reverts, no state change is expected; skip assertion
            assertTrue(true);
        }
    }
}

